files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1d1f2b;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: #e8e9f0;
  padding: 16px;
}

.card {
  background: #282b3a;
  border-radius: 16px;
  padding: 28px 24px;
  width: 100%;
  max-width: 560px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.subtitle {
  font-size: 1rem;
  color: #a0a3b8;
  margin-top: -8px;
}

.palette {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.swatch {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  border: 3px solid transparent;
  background: var(--swatch-color);
  cursor: pointer;
  transition: transform 0.12s, border-color 0.12s, box-shadow 0.12s;
}

.swatch:hover {
  transform: scale(1.08);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.25);
}

.swatch:focus-visible {
  outline: 3px solid #7cc4ff;
  outline-offset: 2px;
}

.swatch.selected {
  border-color: #ffffff;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.35);
}

.swatch:active {
  transform: scale(0.96);
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  font: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: 10px;
  border: 2px solid #3d4157;
  background: #31354a;
  color: #e8e9f0;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s, transform 0.08s;
}

.btn:hover {
  background: #3d4157;
  border-color: #5a5f7a;
}

.btn:focus-visible {
  outline: 3px solid #7cc4ff;
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn[aria-pressed="true"] {
  background: #e63946;
  border-color: #e63946;
  color: #fff;
}

.grid {
  display: grid;
  grid-template-columns: repeat(16, 1fr);
  gap: 2px;
  background: #1d1f2b;
  padding: 4px;
  border-radius: 10px;
  aspect-ratio: 1 / 1;
  width: 100%;
}

.cell {
  background: #f1faee;
  border: none;
  border-radius: 2px;
  cursor: pointer;
  padding: 0;
  transition: background 0.06s, box-shadow 0.06s;
}

.cell:hover {
  box-shadow: inset 0 0 0 2px rgba(0, 0, 0, 0.25);
}

.cell:focus-visible {
  outline: 2px solid #7cc4ff;
  outline-offset: 1px;
  z-index: 1;
}

.cell:active {
  opacity: 0.8;
}

.counter {
  font-size: 1rem;
  color: #a0a3b8;
  text-align: center;
}

.counter span {
  font-weight: 700;
  color: #e8e9f0;
}

@media (max-width: 400px) {
  .card {
    padding: 20px 16px;
    gap: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .swatch {
    width: 38px;
    height: 38px;
  }
  .btn {
    padding: 8px 16px;
  }
}

const GRID_SIZE = 16;
const TOTAL = GRID_SIZE * GRID_SIZE;
const DEFAULT_COLOR = '#f1faee';

const grid = document.getElementById('grid');
const palette = document.getElementById('palette');
const eraserBtn = document.getElementById('eraser');
const clearBtn = document.getElementById('clear');
const countEl = document.getElementById('count');

let selectedColor = '#e63946';
let eraserActive = false;

const cells = [];

for (let i = 0; i < TOTAL; i++) {
  const cell = document.createElement('button');
  cell.className = 'cell';
  cell.type = 'button';
  cell.dataset.color = DEFAULT_COLOR;
  cell.setAttribute('aria-label', `Row ${Math.floor(i / GRID_SIZE) + 1}, column ${(i % GRID_SIZE) + 1}`);
  cell.addEventListener('click', () => paint(cell));
  grid.appendChild(cell);
  cells.push(cell);
}

function paint(cell) {
  const newColor = eraserActive ? DEFAULT_COLOR : selectedColor;
  cell.style.background = newColor;
  cell.dataset.color = newColor;
  updateCount();
}

function updateCount() {
  const painted = cells.filter(c => c.dataset.color !== DEFAULT_COLOR).length;
  countEl.textContent = painted;
}

palette.addEventListener('click', (e) => {
  const swatch = e.target.closest('.swatch');
  if (!swatch) return;
  selectedColor = swatch.dataset.color;
  eraserActive = false;
  eraserBtn.setAttribute('aria-pressed', 'false');
  document.querySelectorAll('.swatch').forEach(s => {
    const isSelected = s === swatch;
    s.classList.toggle('selected', isSelected);
    s.setAttribute('aria-pressed', String(isSelected));
  });
});

eraserBtn.addEventListener('click', () => {
  eraserActive = !eraserActive;
  eraserBtn.setAttribute('aria-pressed', String(eraserActive));
  if (eraserActive) {
    document.querySelectorAll('.swatch').forEach(s => {
      s.classList.remove('selected');
      s.setAttribute('aria-pressed', 'false');
    });
  } else {
    const first = palette.querySelector('.swatch');
    if (first) {
      selectedColor = first.dataset.color;
      first.classList.add('selected');
      first.setAttribute('aria-pressed', 'true');
    }
  }
});

clearBtn.addEventListener('click', () => {
  cells.forEach(cell => {
    cell.style.background = DEFAULT_COLOR;
    cell.dataset.color = DEFAULT_COLOR;
  });
  updateCount();
});

updateCount();
